import "@hotwired/turbo-rails"
import "controllers"
// Import and register all your controllers from the importmap via controllers/**/*_controller
import { application } from "controllers/application"
import { eagerLoadControllersFrom } from "@hotwired/stimulus-loading"
eagerLoadControllersFrom("controllers", application)
class ModeratorGameChannel < ApplicationCable::Channel
  def subscribed
    game = Game.moderator_game_from_token(params[:token], params[:code])
    return reject unless game

    stream_from Game.moderator_channel_name(game.join_code)
  end
end
class GameChannel < ApplicationCable::Channel
  def subscribed
    game = Game.find_by(join_code: params[:code].to_s.upcase)
    return reject unless game

    stream_from Game.channel_name(game.join_code)
  end
end
