#!/usr/bin/env bash
set -euo pipefail

cd "$(dirname "$0")/.."
export RAILS_ENV="${RAILS_ENV:-production}"
export RAILS_SERVE_STATIC_FILES=true
mkdir -p storage tmp/pids tmp/cache

bundle exec rails db:prepare
bundle exec rails assets:precompile

exec bundle exec rails server -b 0.0.0.0 -p "${PORT:-3000}"
Rails.application.routes.draw do
  mount ActionCable.server => "/cable"

  get "up" => "rails/health#show", as: :rails_health_check

  root "home#show"

  get "/moderate/quizzes/import", to: "moderate/quiz_imports#new", as: :new_moderate_quiz_import
  post "/moderate/quizzes/import", to: "moderate/quiz_imports#create", as: :moderate_quiz_import

  namespace :moderate do
    root "quizzes#index"

    resources :quizzes, except: :index do
      member do
        get :export
        get :preview
        post :preview_answer
      end

      resources :games, only: %i[create show], controller: "games" do
        member do
          get :state
          patch :start
          patch :finish
          patch :advance
          patch :end_quiz
          patch :top_winners
          patch :draw_winners
          patch :reset_winners
        end
      end

      resources :questions, except: %i[index show] do
        member do
          patch :move_up
          patch :move_down
          patch :toggle_active
        end
      end
    end
  end

  get "/play/:code", to: "play#show", as: :play
  get "/play/:code/state", to: "play#state", as: :state_play
  post "/play/:code/join", to: "play#join", as: :join_play
  post "/play/:code/answer", to: "play#answer", as: :answer_play
end
class ApplicationController < ActionController::Base
  # The app intentionally has no external dependencies or remote assets.
end
class HomeController < ApplicationController
  def show
    redirect_to moderate_root_path
  end
end
module Moderate
  class BaseController < ApplicationController
    before_action :authenticate_moderator!

    private

    def authenticate_moderator!
      expected_username = ENV["QUIZZY_MODERATOR_USERNAME"].to_s
      expected_password = ENV["QUIZZY_MODERATOR_PASSWORD"].to_s

      authenticate_or_request_with_http_basic("Quizzy moderator") do |username, password|
        expected_username.present? && expected_password.present? &&
          ActiveSupport::SecurityUtils.secure_compare(username.to_s, expected_username) &&
          ActiveSupport::SecurityUtils.secure_compare(password.to_s, expected_password)
      end
    end
  end
end
